#include <vector>
#include <string>

using namespace std;

class Solution {
public:
    vector<bool> camelMatch(vector<string>& queries, string pattern) {
        vector<bool> res;
        for (string& q : queries) {
            int i = 0;
            bool valid = true;
            for (char c : q) {
                if (i < pattern.size() && c == pattern[i]) {
                    i++;
                } else if (isupper(c)) {
                    valid = false;
                    break;
                }
            }
            res.push_back(valid && i == pattern.size());
        }
        return res;
    }
};
